package it.penny.api.mail;

import org.springframework.web.bind.annotation.*;
import org.springframework.security.core.Authentication;
import org.springframework.http.*;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.util.*;
import java.nio.charset.StandardCharsets;

@RestController @RequestMapping("/api/mail")
public class MailController {
 final MailService s;final org.springframework.jdbc.core.JdbcTemplate db;final it.penny.api.security.PennyUserRepository users;final it.penny.api.security.RbacService rbac;final it.penny.api.common.AuditLog audit;
 public MailController(MailService s,org.springframework.jdbc.core.JdbcTemplate db,it.penny.api.security.PennyUserRepository users,it.penny.api.security.RbacService rbac,it.penny.api.common.AuditLog audit){this.s=s;this.db=db;this.users=users;this.rbac=rbac;this.audit=audit;}
 @PostMapping("/connections") public Map<String,Object> connect(Authentication a){return s.connect(a);}
 @GetMapping("/connections") public List<Map<String,Object>> connections(Authentication a){var u=s.require(a,true);return db.queryForList("SELECT id,created_at AS \"createdAt\",expires_at AS \"expiresAt\" FROM penny_mail_connections WHERE user_id=? AND revoked_at IS NULL AND expires_at>now() ORDER BY id DESC",u.id);}
 @DeleteMapping("/connections/{id}") public Map<String,Object> revoke(@PathVariable long id,Authentication a){var u=s.require(a,true);db.update("UPDATE penny_mail_connections SET revoked_at=now() WHERE id=? AND user_id=?",id,u.id);return Map.of("revoked",true);}
 @GetMapping public Map<String,Object> list(@RequestParam long customerId,@RequestParam(defaultValue="") String q,@RequestParam(required=false) Long recordId,@RequestParam(defaultValue="0") int page,Authentication a){
  s.require(a,false);s.customer(customerId);if(q.length()>100||page<0||page>100000)throw MailPayload.bad("Ricerca non valida");if(recordId!=null&&s.record(recordId,a,false)!=customerId)throw MailPayload.bad("Attività di un altro cliente");
  String search="%"+q.toLowerCase(Locale.ROOT).replace("\\","\\\\").replace("%","\\%").replace("_","\\_")+"%";
  String where=" FROM penny_mail_messages m WHERE customer_id=? AND (?::bigint IS NULL OR EXISTS(SELECT 1 FROM penny_mail_record_links l WHERE l.message_id=m.id AND l.record_id=?)) AND (lower(subject) LIKE ? OR lower(sender) LIKE ? OR lower(recipients) LIKE ? OR lower(body_text) LIKE ? OR EXISTS(SELECT 1 FROM penny_mail_comments c WHERE c.message_id=m.id AND lower(c.body) LIKE ?))";
  Object[] args={customerId,recordId,recordId,search,search,search,search,search};var p=new ArrayList<>(Arrays.asList(args));p.add(20);p.add(page*20);
  return Map.of("items",db.queryForList("SELECT m.id,m.subject,m.subject AS name,m.sender,m.recipients,m.sent_at AS \"sentAt\",m.conversation_key AS \"conversationKey\",(SELECT count(*) FROM penny_mail_attachments f WHERE f.message_id=m.id) AS attachments,(SELECT count(*) FROM penny_mail_comments c WHERE c.message_id=m.id) AS comments"+where+" ORDER BY sent_at DESC,id DESC LIMIT ? OFFSET ?",p.toArray()),"total",db.queryForObject("SELECT count(*)"+where,Long.class,args));
 }
 @GetMapping("/activity-options") public Map<String,Object> options(@RequestParam long customerId,@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="0") int page,Authentication a){s.require(a,true);s.customer(customerId);if(q.length()>100||page<0||page>100000)throw MailPayload.bad("Ricerca troppo lunga");var u=users.findByEmailIgnoreCase(a.getName()).orElseThrow();var kinds=java.util.stream.Stream.of("TRAINING","CONTRACT","DEVELOPMENT","TECHNICAL","COMMERCIAL","INTERVENTION").filter(k->rbac.allowed(u.id,it.penny.api.records.CustomerRecordService.permission(k)+"_WRITE")).toList();if(kinds.isEmpty())return Map.of("items",List.of(),"total",0);var n=new org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate(db);var p=new org.springframework.jdbc.core.namedparam.MapSqlParameterSource("customer",customerId).addValue("kinds",kinds).addValue("q","%"+q.toLowerCase(Locale.ROOT).replace("\\","\\\\").replace("%","\\%").replace("_","\\_")+"%");p.addValue("offset",page*20);String w=" FROM penny_customer_records WHERE customer_id=:customer AND kind IN (:kinds) AND deleted_at IS NULL AND lower(name) LIKE :q";return Map.of("items",n.queryForList("SELECT id,name,kind"+w+" ORDER BY name,id LIMIT 20 OFFSET :offset",p),"total",n.queryForObject("SELECT count(*)"+w,p,Long.class));}
 @GetMapping("/{id}") public Map<String,Object> detail(@PathVariable long id,Authentication a){s.require(a,false);var result=s.message(id);result.put("attachments",db.queryForList("SELECT id,filename,octet_length(content) AS size,inline_image AS \"inlineImage\" FROM penny_mail_attachments WHERE message_id=? ORDER BY id",id));result.put("comments",db.queryForList("SELECT c.id,c.body,c.created_at AS \"createdAt\",u.full_name AS author FROM penny_mail_comments c JOIN penny_users u ON u.id=c.author_id WHERE message_id=? ORDER BY c.id",id));
  var links=db.queryForList("SELECT r.id,r.name,r.kind FROM penny_mail_record_links l JOIN penny_customer_records r ON r.id=l.record_id WHERE l.message_id=? AND r.deleted_at IS NULL ORDER BY r.id",id);links.removeIf(row->{try{s.record(((Number)row.get("id")).longValue(),a,false);row.put("canWrite",rbac.allowed(users.findByEmailIgnoreCase(a.getName()).orElseThrow().id,it.penny.api.records.CustomerRecordService.permission((String)row.get("kind"))+"_WRITE"));return false;}catch(ResponseStatusException e){return true;}});result.put("activities",links);result.put("conversation",db.queryForList("SELECT id,subject,sender,sent_at AS \"sentAt\" FROM penny_mail_messages WHERE customer_id=? AND conversation_key=? ORDER BY sent_at,id LIMIT 100",result.get("customerId"),result.get("conversationKey")));return result;}
 @GetMapping("/{id}/original") public ResponseEntity<byte[]> original(@PathVariable long id,Authentication a){s.require(a,false);s.message(id);var row=db.queryForMap("SELECT original_name,original_data FROM penny_mail_messages WHERE id=?",id);return file((String)row.get("original_name"),(byte[])row.get("original_data"));}
 @GetMapping("/{id}/attachments/{fileId}") public ResponseEntity<byte[]> attachment(@PathVariable long id,@PathVariable long fileId,Authentication a){s.require(a,false);s.message(id);var rows=db.queryForList("SELECT filename,content FROM penny_mail_attachments WHERE id=? AND message_id=?",fileId,id);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);return file((String)rows.getFirst().get("filename"),(byte[])rows.getFirst().get("content"));}
 static ResponseEntity<byte[]> file(String name,byte[] bytes){return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(name.replaceAll("[\\r\\n\\\\/]","_"),StandardCharsets.UTF_8).build().toString()).header(HttpHeaders.CACHE_CONTROL,"no-store").header("X-Content-Type-Options","nosniff").body(bytes);}
 public record Comment(String body){}
 @PostMapping("/{id}/comments") @Transactional public Map<String,Object> comment(@PathVariable long id,@RequestBody Comment body,Authentication a){var u=s.require(a,true);s.message(id);if(body.body()==null||body.body().isBlank()||body.body().length()>5000)throw MailPayload.bad("Commento: da 1 a 5000 caratteri");var comment=db.queryForObject("INSERT INTO penny_mail_comments(message_id,author_id,body) VALUES (?,?,?) RETURNING id",Long.class,id,u.id,body.body().trim());audit.record(a,"MAIL_COMMENTED","MAIL",id,Map.of("commentId",comment));return Map.of("id",comment);}
 public record Link(Long recordId){}
 @PostMapping("/{id}/activities") @Transactional public Map<String,Object> link(@PathVariable long id,@RequestBody Link input,Authentication a){var u=s.require(a,true);var mail=s.message(id);if(input.recordId()==null||s.record(input.recordId(),a,true)!=((Number)mail.get("customerId")).longValue())throw MailPayload.bad("L'attività deve appartenere allo stesso cliente");db.update("INSERT INTO penny_mail_record_links(message_id,record_id,customer_id,linked_by) VALUES (?,?,?,?) ON CONFLICT DO NOTHING",id,input.recordId(),mail.get("customerId"),u.id);audit.record(a,"MAIL_ACTIVITY_LINKED","MAIL",id,Map.of("recordId",input.recordId()));return Map.of("linked",true);}
 @DeleteMapping("/{id}/activities/{recordId}") @Transactional public Map<String,Object> unlink(@PathVariable long id,@PathVariable long recordId,Authentication a){s.require(a,true);s.message(id);s.record(recordId,a,true);db.update("DELETE FROM penny_mail_record_links WHERE message_id=? AND record_id=?",id,recordId);audit.record(a,"MAIL_ACTIVITY_UNLINKED","MAIL",id,Map.of("recordId",recordId));return Map.of("linked",false);}
}
